import { NextResponse } from "next/server";
import { db } from "@/db";
import { contactMessages } from "@/db/schema";
import { sanitizeContactInput, validateContactInput } from "@/lib/contact-validation";
import nodemailer from "nodemailer";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const SMTP_HOST = process.env.SMTP_HOST;
const SMTP_PORT = parseInt(process.env.SMTP_PORT ?? "587", 10);
const SMTP_USER = process.env.SMTP_USER;
const SMTP_PASSWORD = process.env.SMTP_PASSWORD;
const CONTACT_EMAIL = process.env.CONTACT_EMAIL ?? "anasl1gziri@gmail.com";

if (!SMTP_HOST || !SMTP_USER || !SMTP_PASSWORD) {
  console.warn("[contact] SMTP credentials not configured. Email sending will fail.");
}

const transporter = nodemailer.createTransport({
  host: SMTP_HOST,
  port: SMTP_PORT,
  secure: SMTP_PORT === 465,
  auth: {
    user: SMTP_USER,
    pass: SMTP_PASSWORD,
  },
});

const WINDOW_MS = 10 * 60 * 1000;
const MAX_PER_WINDOW = 5;
const hits = new Map<string, number[]>();

function isRateLimited(ip: string): boolean {
  const now = Date.now();
  const recent = (hits.get(ip) ?? []).filter((t) => now - t < WINDOW_MS);
  if (recent.length >= MAX_PER_WINDOW) {
    hits.set(ip, recent);
    return true;
  }
  recent.push(now);
  hits.set(ip, recent);
  return false;
}

export async function POST(request: Request) {
  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ ok: false, error: "invalid_json" }, { status: 400 });
  }

  const honeypot = (body as Record<string, unknown> | null)?.website;
  if (typeof honeypot === "string" && honeypot.length > 0) {
    return NextResponse.json({ ok: true });
  }

  const ip =
    request.headers.get("x-forwarded-for")?.split(",")[0]?.trim() ||
    request.headers.get("x-real-ip") ||
    "unknown";

  if (isRateLimited(ip)) {
    return NextResponse.json({ ok: false, error: "rate_limited" }, { status: 429 });
  }

  const input = sanitizeContactInput(body);
  const errors = validateContactInput(input);
  if (Object.keys(errors).length > 0) {
    return NextResponse.json({ ok: false, error: "validation", errors }, { status: 422 });
  }

  const rawLocale = (body as Record<string, unknown>).locale;
  const locale = rawLocale === "en" ? "en" : "fr";

  try {
    const [saved] = await db
      .insert(contactMessages)
      .values({ ...input, locale })
      .returning({ id: contactMessages.id, createdAt: contactMessages.createdAt });

    const { name, email, subject, message } = input;

    if (!SMTP_HOST || !SMTP_USER || !SMTP_PASSWORD) {
      console.error("[contact] SMTP not configured, cannot send email");
      return NextResponse.json({ ok: false, error: "server_error" }, { status: 500 });
    }

    await Promise.allSettled([
      transporter.sendMail({
        from: `"Portfolio Contact" <${SMTP_USER}>`,
        to: CONTACT_EMAIL,
        replyTo: email,
        subject: `New Contact: ${subject}`,
        text: `
New Contact Form Submission

Name: ${name}
Email: ${email}
Subject: ${subject}

Message:
${message}

---
Submitted at: ${new Date().toISOString()}
        `.trim(),
        html: `
          <div style="font-family: sans-serif; line-height: 1.5; color: #333;">
            <h2>New Contact Form Submission</h2>
            <p><strong>Name:</strong> ${name}</p>
            <p><strong>Email:</strong> ${email}</p>
            <p><strong>Subject:</strong> ${subject}</p>
            <p><strong>Message:</strong></p>
            <p style="white-space: pre-wrap;">${message}</p>
            <hr style="border: 0; border-top: 1px solid #eee; margin: 20px 0;" />
            <p><small>Submitted at: ${new Date().toISOString()}</small></p>
          </div>
        `,
      }),
      transporter.sendMail({
        from: `"Portfolio Contact" <${SMTP_USER}>`,
        to: email,
        subject: "Thanks for reaching out!",
        text: `
Hi ${name},

Thanks for contacting me! I've received your message and will get back to you soon.

Your message:
${message}

---
Anas Lagziri - Full Stack Developer
        `.trim(),
        html: `
          <div style="font-family: sans-serif; line-height: 1.5; color: #333;">
            <p>Hi ${name},</p>
            <p>Thanks for contacting me! I've received your message and will get back to you soon.</p>
            <p><strong>Your message:</strong></p>
            <p style="white-space: pre-wrap;">${message}</p>
            <hr style="border: 0; border-top: 1px solid #eee; margin: 20px 0;" />
            <p><small>Anas Lagziri - Full Stack Developer</small></p>
          </div>
        `,
      }),
    ]);

    return NextResponse.json({ ok: true, id: saved.id, createdAt: saved.createdAt }, { status: 201 });
  } catch (error) {
    console.error("[contact] failed to store message or send email", error);
    return NextResponse.json({ ok: false, error: "server_error" }, { status: 500 });
  }
}